import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Login = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', { email, password });
      localStorage.setItem('vrx_token', res.data.token);
      localStorage.setItem('vrx_user', JSON.stringify(res.data.user));
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Invalid email or password');
    }
    setLoading(false);
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #F8FAFC 0%, #E2E8F0 100%)' }}>
      <div className="bg-white p-5 rounded-4 shadow" style={{ width: '100%', maxWidth: '450px' }}>
        <div className="text-center mb-4">
          <Link to="/" style={{ textDecoration: 'none', color: 'var(--dark)' }}>
            <h2 className="fw-bold"><i className="fa-solid fa-bolt" style={{ color: '#2563EB' }}></i> VehicleRentX</h2>
          </Link>
          <h3 className="mt-4 fw-bold">Welcome Back</h3>
          <p className="text-muted">Sign in to manage your rentals.</p>
        </div>
        {error && <div className="alert alert-danger py-2">{error}</div>}
        <form onSubmit={handleLogin}>
          <div className="mb-3">
            <label className="form-label fw-bold small text-muted">EMAIL ADDRESS</label>
            <input type="email" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="student@university.edu" value={email} onChange={(e) => setEmail(e.target.value)} />
          </div>
          <div className="mb-4">
            <label className="form-label fw-bold small text-muted">PASSWORD</label>
            <input type="password" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)} />
          </div>
          <button type="submit" className="btn btn-primary-custom w-100 py-3" disabled={loading}>
            {loading ? <><i className="fa-solid fa-spinner fa-spin me-2"></i>Signing in...</> : 'Sign In'}
          </button>
        </form>
        <div className="text-center mt-4 text-muted">
          Don't have an account? <Link to="/register" className="fw-bold text-primary">Create one</Link>
        </div>
      </div>
    </div>
  );
};

export default Login;
